class Solution {
    public: int minSkips(vector<int>& dist,int speed,int hoursBefore){
        const long long INF=LLONG_MAX/4;
        vector<long long> dp(dist.size()+1,INF);
        dp[0]=0;
        for(int road=0;road<(int)dist.size();++road){
            vector<long long> next(dist.size()+1,INF);
            for(int skipped=0;skipped<=road;++skipped)if(dp[skipped]<INF){
                long long arrival=dp[skipped]+dist[road];
                long long waited=road+1==(int)dist.size()?arrival:(arrival+speed-1)/speed*speed;
                next[skipped]=min(next[skipped],waited);
                if(road+1<(int)dist.size())next[skipped+1]=min(next[skipped+1],arrival);
            }
            dp.swap(next);
        }
        long long limit=1LL*hoursBefore*speed;
        for(int skipped=0;skipped<(int)dp.size();++skipped)if(dp[skipped]<=limit)return skipped;
        return -1;
    }
};
